package com.bank.histogram;

import java.util.*;
import java.util.logging.*;

public class CharCountDemo {
    private static final Logger log = Logger.getLogger("Histogram");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        HistogramService service = new HistogramService();
        Map<Character, Long> counts = service.charCounts("balance");
        log.info(() -> "char counts for 'balance': " + counts);
    }
}

// ─── Would be in service/HistogramService.java ───
class HistogramService {
    Map<Character, Long> charCounts(String s) {
        return s.chars()
            .mapToObj(c -> (char) c)                             // IntStream → Character
            .collect(java.util.stream.Collectors.groupingBy(
                ch -> ch,
                TreeMap::new,                                     // sorted by character
                java.util.stream.Collectors.counting()));         // frequency as Long
    }
}
